tasks.command:
& {
$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$stamp = (Get-Date -Format 'yyyyMMdd-HHmmssfff') + '-' + [guid]::NewGuid().ToString('N').Substring(0, 6)
$directory = Join-Path $root ('.local/old-web-agent-' + $stamp)
$source = Join-Path $directory 'backend'
$reports = Join-Path $directory 'reports'
New-Item -ItemType Directory -Path $source, $reports | Out-Null
$files = @(git ls-files -- backend/app backend/migrations backend/tests backend/pyproject.toml backend/alembic.ini)
if ($LASTEXITCODE -ne 0) { throw 'Source inventory failed.' }
$captured = foreach ($file in $files) {
  if ($file -notmatch '^backend/(app/.*\.py|migrations/.*\.py|tests/.*\.py|pyproject\.toml|alembic\.ini)$') { continue }
  $entry = Get-Item -LiteralPath $file
  if (($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Source links are not accepted.' }
  $before = (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash
  $target = Join-Path $directory $file
  New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
  Copy-Item -LiteralPath $file -Destination $target
  if ((Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -ne $before -or (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash -ne $before) { throw 'Source moved during capture.' }
  [pscustomobject]@{ Path = $file; SHA256 = $before }
}
$captured | ConvertTo-Json -Depth 3 | Out-File -LiteralPath (Join-Path $directory 'inputs.json') -Encoding utf8
Write-Output ('Source snapshot: ' + $directory)
$docker = 'C:/Program Files/Docker/Docker/resources/bin/docker.exe'
& $docker run --rm --pull never --network community-platform_default --mount ('type=bind,source=' + $source + ',target=/app,readonly') --mount ('type=bind,source=' + $reports + ',target=/reports') --workdir /app -e COMMUNITY_ENVIRONMENT=test -e COMMUNITY_DATABASE_URL=postgresql+psycopg://community_test:synthetic-tests-only@test-db:5432/community_test -e COMMUNITY_AGENT_MODEL_URL= -e COMMUNITY_AGENT_MODEL_NAME= -e COMMUNITY_AGENT_MODEL_KEY= -e COMMUNITY_AGENT_WEB_KEY= community-platform-tests pytest -q --tb=short -p no:cacheprovider --junitxml=/reports/agent.xml tests/test_agent_runtime.py tests/test_agent_llm.py tests/test_agent_kinds.py tests/test_agent_auto_approve.py tests/test_agent_mentions.py tests/test_agent_registry.py tests/test_agent_metrics.py
$exitCode = $LASTEXITCODE
$changedSource = @($captured | Where-Object { (Get-FileHash -LiteralPath (Join-Path $directory $_.Path) -Algorithm SHA256).Hash -ne $_.SHA256 } | ForEach-Object { $_.Path })
$changedWorkspace = @($captured | Where-Object { -not (Test-Path -LiteralPath $_.Path) -or (Get-FileHash -LiteralPath $_.Path -Algorithm SHA256).Hash -ne $_.SHA256 } | ForEach-Object { $_.Path })
$result = [pscustomobject]@{ ExitCode = $exitCode; CapturedInputs = @($captured).Count; ChangedSnapshot = $changedSource; ChangedWorkspace = $changedWorkspace; Report = (Join-Path $reports 'agent.xml') }
$result | ConvertTo-Json -Depth 4 | Out-File -LiteralPath (Join-Path $directory 'result.json') -Encoding utf8
$result | ConvertTo-Json -Depth 4
if ($exitCode -ne 0 -or $changedSource.Count -gt 0 -or $changedWorkspace.Count -gt 0) { throw 'Agent qualification failed or source changed; evidence retained.' }
}

& {
$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$reports = @('backend/.local/old-web-backend-full-20261009.xml', '.local/old-web-components-20261009.xml', '.local/old-web-client-20261009.xml', '.local/old-web-api-transport-reviewed-20261009.xml', '.local/old-web-smoke-20261009.xml')
$results = foreach ($report in $reports) {
  $full = Join-Path $root $report
  if (-not (Test-Path -LiteralPath $full -PathType Leaf)) { [pscustomobject]@{ Report = $report; State = 'Not finalized' }; continue }
  $document = New-Object System.Xml.XmlDocument
  try { $document.Load($full) } catch { [pscustomobject]@{ Report = $report; State = 'Invalid or incomplete XML' }; continue }
  $cases = $document.SelectNodes('//testcase')
  if ($cases.Count -lt 1) { throw 'An empty report is not verification.' }
  $failed = $document.SelectNodes('//testcase[failure or error]')
  $skipped = $document.SelectNodes('//testcase[skipped]')
  [pscustomobject]@{ Report = $report; State = 'Finalized'; Tests = $cases.Count; Failed = $failed.Count; Skipped = $skipped.Count; FailingNames = @($failed | ForEach-Object { $_.name }) }
}
$inputs = Get-Content -LiteralPath '.local/old-web-backend-inputs-20261009.json' -Raw | ConvertFrom-Json
$changed = foreach ($inputFile in $inputs) {
  if ($inputFile.Path -notmatch '^backend/(app/.*\.py|migrations/.*\.py|tests/.*\.py|pyproject\.toml|Dockerfile)$') { throw 'Unexpected manifest path.' }
  if (-not (Test-Path -LiteralPath $inputFile.Path -PathType Leaf)) { $inputFile.Path; continue }
  if ((Get-FileHash -LiteralPath $inputFile.Path -Algorithm SHA256).Hash -ne $inputFile.SHA256) { $inputFile.Path }
}
$services = @(& 'C:/Program Files/Docker/Docker/resources/bin/docker.exe' ps --filter 'name=community-platform' --format '{{.Names}}|{{.Status}}')
if ($LASTEXITCODE -ne 0) { throw 'Docker status failed.' }
$health = Invoke-RestMethod -Uri 'http://127.0.0.1:8000/health/ready' -TimeoutSec 15 -MaximumRedirection 0
$record = [pscustomobject]@{ CheckedAt = [DateTime]::UtcNow.ToString('o'); Reports = @($results); BackendInputs = @($inputs).Count; ChangedBackendInputs = @($changed); ApiStatus = $health.status; Services = $services }
$output = '.local/old-web-evidence-' + (Get-Date -Format 'yyyyMMdd-HHmmssfff') + '.json'
$record | ConvertTo-Json -Depth 6 | Out-File -LiteralPath $output -Encoding utf8
Write-Output $output
$record | ConvertTo-Json -Depth 6
}

& {
$captured = @(& node .local/blueprint-audit-run.mjs --snapshot-only)
if ($LASTEXITCODE -ne 0) { throw 'Source snapshot failed' }
$captured | Write-Output
$source = @($captured | Where-Object { $_ -match '^Snapshot: ' } | ForEach-Object { $_.Substring(10) })
if ($source.Count -ne 1) { throw 'Expected one source snapshot' }
& (Join-Path $env:JAVA_HOME 'bin/java.exe') -classpath (Join-Path $source[0] 'android/gradle/wrapper/gradle-wrapper.jar') org.gradle.wrapper.GradleWrapperMain -p (Join-Path $source[0] 'android') :app:testDebugUnitTest --tests com.community.platform.feature.community.CommunityClassificationTest --tests com.community.platform.feature.community.ModerationTest --tests com.community.platform.feature.messaging.MessagingTest --tests com.community.platform.feature.messaging.MessagingLiveTest --tests com.community.platform.feature.messaging.OutboxTest --tests com.community.platform.feature.realtime.LiveUpdatesTest --offline --console=plain --no-daemon --max-workers=2
if ($LASTEXITCODE -ne 0) { throw 'Native qualification regressions failed' }
}

& {
$busy = @(Get-CimInstance Win32_Process | Where-Object { ($_.Name -eq 'java.exe' -and $_.CommandLine -match 'GradleWrapperMain|Gradle Test Executor') -or $_.Name -match '^(qemu-system-x86_64(-headless)?|emulator)\.exe$' })
if ($busy.Count -gt 0) {
$busy | Select-Object ProcessId,ParentProcessId,Name,CommandLine | Format-List
throw 'Native resources are in use; no focused build was started.'
}
& node .local/blueprint-audit-run.mjs --android-focused .local/blueprint-audit-2026-10-03T10-49-07-626Z-4c7ae56f com.community.platform.feature.planning.TaskViewModelTest com.community.platform.feature.realtime.LiveUpdatesTest
if ($LASTEXITCODE -ne 0) { throw 'Focused planning and realtime verification failed; preserve the reports.' }
}

& {
& docker compose -f infra/compose.yaml up -d --no-build --pull never --no-recreate --wait db mail
if ($LASTEXITCODE -ne 0) { throw 'Database and mail startup failed' }
$head = @(& docker compose -f infra/compose.yaml exec -T db psql -U community -d community -At -c 'SELECT version_num FROM alembic_version')
if ($LASTEXITCODE -ne 0 -or ($head -join '').Trim() -ne '0040') { throw 'Database does not match qualification source migration 0040; no migration was attempted' }
& docker compose -f infra/compose.yaml start api identity-mail-worker reminder-worker export-worker account-deletion-worker
if ($LASTEXITCODE -ne 0) { throw 'Local API or worker startup failed' }
Write-Output 'Existing local services resumed against migration 0040; no rebuild, migration or reset.'
}

& {
    $previous = $env:COMMUNITY_AGENT_MODEL_LIVE
    try {
        $env:COMMUNITY_AGENT_MODEL_LIVE = '1'
        & node --test --test-concurrency=1 --test-name-pattern='^agent read-only:' --test-reporter=spec --test-reporter=junit --test-reporter-destination=stdout --test-reporter-destination=.local/agent-readonly-live-model-20261004.xml tests/e2e/identity.test.mjs
        if ($LASTEXITCODE -ne 0) { throw 'The model-enabled read-only agent journey failed.' }
    } finally {
        $env:COMMUNITY_AGENT_MODEL_LIVE = $previous
    }
}

& {
    $captured = @(& node .local/blueprint-audit-run.mjs --snapshot-only)
    $captured | Write-Output
    if ($LASTEXITCODE -ne 0) { throw 'Source capture failed; tests were not started.' }
    $snapshot = ($captured | Where-Object { $_.StartsWith('Snapshot: ') }).Substring(10)
    if (-not $snapshot) { throw 'No captured source path was returned.' }
    $backend = Join-Path $snapshot 'backend'
    & docker compose -f infra/compose.yaml --profile test run --rm --pull never -e PYTHONDONTWRITEBYTECODE=1 -v "${backend}:/app:ro" -v "${snapshot}:/evidence" tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agents.py tests/test_agent_evaluation.py tests/test_space_agent_switch.py tests/test_agent_model.py tests/test_agent_model_budget.py tests/test_agent_metrics.py tests/test_openapi.py --junitxml=/evidence/agent-backend.xml
    if ($LASTEXITCODE -ne 0) { throw "Agent backend verification failed; evidence is in $snapshot" }
}

& {
    $captured = @(& node .local/blueprint-audit-run.mjs --snapshot-only)
    $captured | Write-Output
    if ($LASTEXITCODE -ne 0) { throw 'Agent source capture failed.' }
    $snapshot = ($captured | Where-Object { $_.StartsWith('Snapshot: ') }).Substring(10)
    if (-not $snapshot) { throw 'Source capture returned no path.' }
    & node .local/blueprint-audit-run.mjs --android-focused $snapshot com.community.platform.feature.agents.AgentTest
    if ($LASTEXITCODE -ne 0) { throw "Native Agent verification failed; preserve evidence at $snapshot" }
}

& {
    $ErrorActionPreference = 'Continue'
    $container = 'community-platform-tests-run-79a81ade1ed2'
    $metadata = @(& docker inspect $container | ConvertFrom-Json)[0]
    if ($LASTEXITCODE -ne 0 -or -not $metadata) { throw 'Expected parity container is unavailable' }
    if (-not ($metadata.Config.Env -contains 'COMMUNITY_AGENT_LANGGRAPH_ENABLED=1')) { throw 'Container is not graph-enabled' }
    if (-not ($metadata.Mounts | Where-Object { $_.Destination -eq '/app' -and $_.Source -match '57d11e97' -and -not $_.RW })) { throw 'Container does not use the expected read-only frozen source' }
    if (-not ($metadata.Mounts | Where-Object { $_.Destination -eq '/runtime' -and $_.Source -match 'runtime-20261005-a' -and -not $_.RW })) { throw 'Container does not use the verified read-only runtime' }
    $snapshot = Join-Path (Get-Location) '.local/blueprint-audit-2026-10-05T05-22-26-030Z-57d11e97'
    Write-Output 'Confirmed the existing graph-enabled parity run; attaching to its log, not starting another test.'
    $output = @(& docker logs --follow $container 2>&1)
    $output | ForEach-Object { $_.ToString() } | Out-File -Encoding utf8 (Join-Path $snapshot 'langgraph-parity-collected.log')
    $output | Select-Object -Last 50
    $reportPath = Join-Path $snapshot 'langgraph-parity.xml'
    if (-not (Test-Path -LiteralPath $reportPath)) { throw 'The parity run produced no JUnit report' }
    [xml]$report = Get-Content -LiteralPath $reportPath -Raw
    $cases = $report.SelectNodes('//testcase')
    $failures = $report.SelectNodes('//testcase/failure')
    $errors = $report.SelectNodes('//testcase/error')
    $skips = $report.SelectNodes('//testcase/skipped')
    Write-Output ('Tests=' + $cases.Count + '; failures=' + $failures.Count + '; errors=' + $errors.Count + '; skipped=' + $skips.Count)
    if ($cases.Count -eq 0 -or $failures.Count -ne 0 -or $errors.Count -ne 0 -or $skips.Count -ne 0) { throw 'Frozen Linux graph parity did not pass completely' }
}

& {
    $metadata = & docker inspect community-platform-tests-run-79a81ade1ed2 | ConvertFrom-Json
    if ($LASTEXITCODE -ne 0) { throw 'Graph container inspection failed' }
    foreach ($container in $metadata) {
        [pscustomobject]@{ Name = $container.Name; Status = $container.State.Status; GraphEnabled = ($container.Config.Env -contains 'COMMUNITY_AGENT_LANGGRAPH_ENABLED=1'); Command = $container.Config.Cmd; Mounts = @($container.Mounts | Select-Object Source,Destination,RW); Binds = $container.HostConfig.Binds } | ConvertTo-Json -Depth 7
    }
}

& {
    $env:COMMUNITY_T195_BACKEND = (Resolve-Path -LiteralPath '.local/blueprint-audit-2026-10-05T05-22-26-030Z-57d11e97/backend').Path
    $env:COMMUNITY_T195_EVIDENCE = (Resolve-Path -LiteralPath '.local/t195/build-20261005-a').Path
    $configuration = & docker compose -f infra/compose.yaml -f infra/compose.agent-langgraph.yaml -f .local/t195-qualification.compose.yaml config --format json | ConvertFrom-Json
    if ($LASTEXITCODE -ne 0) { throw 'Graph Compose configuration failed' }
    $mounts = $configuration.services.tests.volumes
    foreach ($target in @('/app','/agent-runtime')) {
        $mount = @($mounts | Where-Object { $_.target -eq $target })
        if ($mount.Count -ne 1 -or $mount[0].read_only -ne $true) { throw ('Expected read-only mount: ' + $target) }
    }
    if ($configuration.services.tests.environment.COMMUNITY_AGENT_LANGGRAPH_ENABLED -ne '1') { throw 'Graph gate missing from test configuration' }
    $mounts | Select-Object source,target,read_only | Format-Table -AutoSize
    Write-Output 'Explicit frozen-source and runtime read-only Compose configuration validated; no service started.'
}

& {
    $env:COMMUNITY_T195_BACKEND = (Resolve-Path -LiteralPath '.local/blueprint-audit-2026-10-05T05-22-26-030Z-57d11e97/backend').Path
    $env:COMMUNITY_T195_EVIDENCE = (Resolve-Path -LiteralPath '.local/t195/build-20261005-a').Path
    $configuration = & docker compose -f infra/compose.yaml -f infra/compose.agent-langgraph.yaml -f .local/t195-qualification.compose.yaml config --format json | ConvertFrom-Json
    if ($LASTEXITCODE -ne 0) { throw 'Compose inspection failed' }
    [pscustomobject]@{ testMounts = $configuration.services.tests.volumes; apiMounts = $configuration.services.api.volumes; graphEnabled = $configuration.services.tests.environment.COMMUNITY_AGENT_LANGGRAPH_ENABLED } | ConvertTo-Json -Depth 6
}

& {
    $runtime = (Resolve-Path -LiteralPath '.local/t195/runtime-20261005-a/site-packages').Path
    $backend = (Resolve-Path -LiteralPath 'backend').Path
    & docker run --rm --pull never --network none --read-only --cap-drop ALL --security-opt no-new-privileges -e PYTHONDONTWRITEBYTECODE=1 -e PYTHONPATH=/runtime:/app -e COMMUNITY_AGENT_LANGGRAPH_ENABLED=1 -v "${backend}:/app:ro" -v "${runtime}:/runtime:ro" --entrypoint python3 community-platform-tests -m unittest discover -s /app/tests -p test_agent_graph.py -v
    if ($LASTEXITCODE -ne 0) { throw 'Graph thread/session boundary failed' }
}

& {
    $report = '.local/t195/native-phone-readiness-20261005.json'
    if (Test-Path -LiteralPath $report) { Get-Content -LiteralPath $report -Raw | ConvertFrom-Json | Select-Object completedWithinLimit,exitCode | Format-List }
    Get-CimInstance Win32_Process | Where-Object { $_.Name -match '^(adb|qemu-system-x86_64(-headless)?)\.exe$' -and ($_.ProcessId -eq 23176 -or $_.CommandLine -match 'emulator-5584.*phone') } | Select-Object ProcessId,ParentProcessId,Name,CreationDate,CommandLine | Format-List
    $adb = 'C:\Users\91961\AppData\Local\Android\sdk\platform-tools\adb.exe'
    $owned = @(Get-CimInstance Win32_Process | Where-Object { $_.ProcessId -eq 23176 -and $_.CommandLine -match 'community_membership_20260923' -and $_.CommandLine -match '-read-only' -and $_.CommandLine -match '-port 5584' })
    if ($owned.Count -ne 1) { throw 'Owned emulator identity is unavailable' }
    $boot = @(& $adb -s emulator-5584 shell getprop sys.boot_completed)
    $phone = @(& $adb -s emulator-5584 shell service check phone)
    $package = @(& $adb -s emulator-5584 shell service check package)
    [pscustomobject]@{ boot = ($boot -join '').Trim(); phone = ($phone -join '').Trim(); package = ($package -join '').Trim() } | ConvertTo-Json
}

& {
    $adb = 'C:\Users\91961\AppData\Local\Android\sdk\platform-tools\adb.exe'
    $owned = @(Get-CimInstance Win32_Process | Where-Object { $_.ProcessId -eq 23176 -and $_.CommandLine -match 'community_membership_20260923' -and $_.CommandLine -match '-read-only' -and $_.CommandLine -match '-port 5584' })
    if ($owned.Count -ne 1) { throw 'Do not operate on an unowned emulator' }
    $process = Get-Process -Id 23176
    try {
        & $adb -s emulator-5584 logcat -d -b crash -t 80 | Out-File -Encoding utf8 '.local/t195/native-unready-crash-20261005.txt'
        & $adb -s emulator-5584 shell dumpsys activity exit-info com.android.phone | Out-File -Encoding utf8 '.local/t195/native-unready-phone-20261005.txt'
        $installed = @(& $adb -s emulator-5584 shell pm list packages com.community.platform.debug)
        if ($LASTEXITCODE -ne 0) { throw 'Could not verify fixture app absence' }
        [pscustomobject]@{ ownedProcess = 23176; installedApp = ($installed -join '').Trim(); testsStarted = 0; reason = 'Boot completed but phone service absent' } | ConvertTo-Json | Out-File -Encoding utf8 '.local/t195/native-unready-result-20261005.json'
    } finally {
        $waiter = @(Get-CimInstance Win32_Process | Where-Object { $_.ProcessId -eq 24436 -and $_.Name -eq 'adb.exe' -and $_.CommandLine -match 'emulator-5584 shell cmd -w phone help' })
        if ($waiter.Count -eq 1) { Stop-Process -Id 24436 }
        & $adb -s emulator-5584 emu kill
        if ($LASTEXITCODE -ne 0) { throw 'Owned unready emulator shutdown was not acknowledged' }
        if (-not $process.WaitForExit(30000)) { throw 'Owned unready emulator did not exit' }
        Write-Output 'Unready owned fixture exited; zero app installations/tests; diagnostics retained.'
    }
}

& {
    $runtime = (Resolve-Path -LiteralPath '.local/t195/runtime-20261005-a/site-packages').Path
    $report = '/app/.local/t232-natural-requests-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & docker compose -f infra/compose.yaml --profile test run --rm --pull never -e PYTHONDONTWRITEBYTECODE=1 -e PYTHONPATH=/runtime:/app -e COMMUNITY_AGENT_LANGGRAPH_ENABLED=1 -v "${runtime}:/runtime:ro" tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agents.py -k 'reported or month_qualifier' "--junitxml=$report"
    if ($LASTEXITCODE -ne 0) { throw 'Natural Agent request regressions failed' }
}

& {
    $previous = $env:COMMUNITY_AGENT_MODEL_LIVE
    try {
        $env:COMMUNITY_AGENT_MODEL_LIVE = '1'
        $report = '.local/t232-real-natural-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
        & node --test --test-concurrency=1 '--test-name-pattern=^agent natural conversation:' --test-reporter=spec --test-reporter=junit --test-reporter-destination=stdout "--test-reporter-destination=$report" tests/e2e/agent-conversation.test.mjs
        if ($LASTEXITCODE -ne 0) { throw 'Real natural Agent journey failed' }
    } finally {
        $env:COMMUNITY_AGENT_MODEL_LIVE = $previous
    }
}

& {
    $runtime = (Resolve-Path -LiteralPath '.local/t195/runtime-20261005-a/site-packages').Path
    $report = '/app/.local/t229-lifecycle-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & docker compose -f infra/compose.yaml --profile test run --rm --no-deps --pull never -e PYTHONDONTWRITEBYTECODE=1 -e PYTHONPATH=/runtime:/app -e COMMUNITY_AGENT_LANGGRAPH_ENABLED=1 -v "${runtime}:/runtime:ro" tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agent_graph.py "--junitxml=$report"
    if ($LASTEXITCODE -ne 0) { throw 'Controlled Agent lifecycle checks failed' }
}

& {
    $running = @(& docker ps --no-trunc --format '{{.Names}} {{.Command}}' | Where-Object { $_ -like '*tests/test_agent_public.py*' })
    if ($running.Count) { throw 'A public Agent test process is already running; preserve it and collect its report before another run.' }
    & docker compose -f infra/compose.yaml --profile test run --rm --no-deps --pull never -e PYTHONDONTWRITEBYTECODE=1 tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agent_public.py --junitxml=/app/.local/t235-public-social-dedicated.xml
    if ($LASTEXITCODE -ne 0) { throw 'Public Agent action checks failed; inspect the retained report.' }
}

& {
    $report = '.local/t229-web-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & node --test --test-concurrency=1 --test-reporter=spec --test-reporter=junit --test-reporter-destination=stdout "--test-reporter-destination=$report" tests/agents-client.test.mjs tests/messaging-agent-client.test.mjs tests/unit/agents-ui.test.mjs
    if ($LASTEXITCODE -ne 0) { throw 'Agent lifecycle web compatibility checks failed' }
}

& {
    $report = '/app/.local/t235-selected-replies-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & docker compose -f infra/compose.yaml --profile test run --rm --no-deps --pull never -e PYTHONDONTWRITEBYTECODE=1 tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agent_public.py -k 'selected or reports' "--junitxml=$report"
    if ($LASTEXITCODE -ne 0) { throw 'Selected reply and report checks failed; preserve the report.' }
}

& {
    $report = '.local/t235-agent-web-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & node --test --test-concurrency=1 --test-reporter=spec --test-reporter=junit --test-reporter-destination=stdout "--test-reporter-destination=$report" tests/agents-client.test.mjs tests/messaging-agent-client.test.mjs
    if ($LASTEXITCODE -ne 0) { throw 'Public Agent web contracts failed' }
}

& {
    $report = '/app/.local/t235-atomic-public-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & docker compose -f infra/compose.yaml --profile test run --rm --no-deps --pull never -e PYTHONDONTWRITEBYTECODE=1 tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agent_public.py -k 'combined_publication_refusal or rolls_back or wellness' "--junitxml=$report"
    if ($LASTEXITCODE -ne 0) { throw 'Public action atomicity checks failed' }
}

& {
    $report = '.local/t235-public-review-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & node --test --test-concurrency=1 --test-name-pattern='public page and post review' --test-reporter=spec --test-reporter=junit --test-reporter-destination=stdout "--test-reporter-destination=$report" tests/unit/agents-ui.test.mjs
    if ($LASTEXITCODE -ne 0) { throw 'Public Agent review screen check failed' }
}

& {
    $report = '/app/.local/t235-request-boundaries-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & docker compose -f infra/compose.yaml --profile test run --rm --no-deps --pull never -e PYTHONDONTWRITEBYTECODE=1 tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agents.py -k 'public_action or forbidden_requests' "--junitxml=$report"
    if ($LASTEXITCODE -ne 0) { throw 'Public request and retained-refusal checks failed' }
}

& {
    $report = '/app/.local/t235-draft-review-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & docker compose -f infra/compose.yaml --profile test run --rm --no-deps --pull never -e PYTHONDONTWRITEBYTECODE=1 tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agent_public.py -k post_draft_and_publication "--junitxml=$report"
    if ($LASTEXITCODE -ne 0) { throw 'Public draft review check failed' }
}

& {
    $running = @(Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'node.exe' -and $_.CommandLine -like '*--test-name-pattern=^agent public content:*' -and $_.CommandLine -like '*agent-conversation.test.mjs*' })
    if ($running.Count) { throw 'A wellness publishing journey is already running; collect its report before retrying.' }
    $previous = $env:COMMUNITY_AGENT_MODEL_LIVE
    try {
        $env:COMMUNITY_AGENT_MODEL_LIVE = '1'
        $report = '.local/t235-live-public-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
        & node --test --test-concurrency=1 '--test-name-pattern=^agent public content:' --test-reporter=spec --test-reporter=junit --test-reporter-destination=stdout "--test-reporter-destination=$report" tests/e2e/agent-conversation.test.mjs
        if ($LASTEXITCODE -ne 0) { throw 'Real Agent wellness publishing journey failed; preserve the report.' }
    } finally {
        $env:COMMUNITY_AGENT_MODEL_LIVE = $previous
    }
}

& {
    $report = '/app/.local/t235-publication-continuation-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.xml'
    & docker compose -f infra/compose.yaml --profile test run --rm --no-deps --pull never -e PYTHONDONTWRITEBYTECODE=1 tests python3 -m pytest -q --tb=short -p no:cacheprovider tests/test_agent_runtime.py -k 'requested_publication_review or full_post_text or publication_never_accepts or public_change_and_approval' "--junitxml=$report"
